-- -----------------------------------------------------------------------------
-- 1. VALIDATION DU POINT DE VENTE #5 ET DU DÉPÔT PRINCIPAL
-- -----------------------------------------------------------------------------

VALUES (5, 5, 'SIT TRANSMISSION SARL', 'SIT TRANSMISSION SARL', TRUE, CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE 
SET nom_point_de_vente = EXCLUDED.nom_point_de_vente,
    nom = EXCLUDED.nom,
    tenant_id = EXCLUDED.tenant_id;

SELECT setval('point_de_vente_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM point_de_vente), 5));

-- Dépôt Principal pour Tenant #5
SELECT 'Dépôt Principal', 'Dépôt central SIT TRANSMISSION', 'Casablanca', CURRENT_TIMESTAMP, TRUE, 5
WHERE NOT EXISTS (SELECT 1 FROM depots WHERE point_de_vente_id = 5);

